  @override
  String get legalDataConsentAuditBody =>
      'DVTech వెంచర్స్ అన్ని సమ్మతి ఈవెంట్‌ల (మంజూరు, సవరణ, ఉపసంహరణ) యొక్క ఆడిట్ ట్రయల్‌ను నిర్వహిస్తుంది, శిక్షణ పైప్‌లైన్‌లలోకి డేటా ప్రవాహాలు, అనామక ధృవీకరణలు మరియు మూడవ పక్ష ప్రాసెసర్ సూచనలను నిర్వహిస్తుంది. అద్దెదారు నిర్వాహకులు గవర్నెన్స్ సెట్టింగ్‌ల డ్యాష్‌బోర్డ్ ద్వారా సమ్మతి ఆడిట్ నివేదికను అభ్యర్థించవచ్చు. మేము వార్షిక AI ఎథిక్స్ మరియు డేటా గవర్నెన్స్ సమీక్షలను నిర్వహిస్తాము.';

