  @override
  String get legalDataConsentNeverUsedBody =>
      'కింది డేటా ఎంపికతో సహా ఎట్టి పరిస్థితుల్లోనూ AI శిక్షణ కోసం ఉపయోగించబడదు: (a) బిల్లింగ్ సమాచారం మరియు చెల్లింపు కార్డ్ డేటా; (బి) పూర్తి అజ్ఞాతీకరణ లేకుండా పూర్తి క్లయింట్ పేర్లు, జాతీయ ID నంబర్లు, పాస్‌పోర్ట్ నంబర్‌లు లేదా బయోమెట్రిక్ డేటా; (సి) ప్రివిలేజ్ హోల్డర్ స్పష్టమైన వ్రాతపూర్వక సమ్మతిని అందిస్తే తప్ప, చట్టపరమైన వృత్తిపరమైన ప్రత్యేకాధికారం ద్వారా రక్షించబడిన కమ్యూనికేషన్‌లు; (d) చట్టపరమైన హోల్డ్ లేదా యాక్టివ్ లిటిగేషన్‌కు సంబంధించిన డేటా; (ఇ) ఆరోగ్యం లేదా వైద్య డేటా; (ఎఫ్) 18 సంవత్సరాల కంటే తక్కువ వయస్సు ఉన్న వినియోగదారుల డేటా.';

