  @override
  String get legalDataConsentRetentionBody =>
      'అనామక శిక్షణ డేటాసెట్‌లు మోడల్ డెవలప్‌మెంట్ కోసం అవసరమైన వ్యవధిలో ఉంచబడతాయి, సాధారణంగా సృష్టి నుండి 24 నెలలు. ఫైన్-ట్యూనింగ్ డేటాసెట్‌లకు 12 నెలల తర్వాత స్పష్టమైన పునః-సమ్మతి అవసరం. అద్దెదారు ఖాతా మూసివేయబడిన తర్వాత, ఆ అద్దెదారు యొక్క కంటెంట్ నుండి పొందిన శిక్షణ డేటా మొత్తం 60 రోజులలోపు ప్రక్షాళన చేయబడుతుంది.';

