  @override
  String get legalDisclaimerJurisdictionBody =>
      'భారతదేశం: AI విశ్లేషణ అనేది కేంద్ర చట్టం, పేర్కొన్న చోట రాష్ట్ర చర్యలు మరియు ప్రచురించబడిన న్యాయ నిర్ణయాలపై ఆధారపడి ఉంటుంది. ఇది జిల్లా కోర్టు-స్థాయి అభ్యాసం, స్థానిక బార్ కస్టమ్స్ లేదా క్రోడీకరించని విధానపరమైన నియమాలను పరిగణనలోకి తీసుకోదు. యునైటెడ్ స్టేట్స్: AI విశ్లేషణ సమాఖ్య చట్టం మరియు ఎంచుకున్న రాష్ట్ర చట్టంపై ఆధారపడి ఉంటుంది. US చట్టపరమైన విశ్లేషణ రాష్ట్ర-నిర్దిష్ట లైసెన్స్ పొందిన న్యాయవాదికి ప్రత్యామ్నాయం కాదు. ధృవీకరించబడిన న్యాయవాది సమీక్ష లేకుండా ఇమ్మిగ్రేషన్, నేర రక్షణ లేదా పన్ను విషయాల కోసం అందుబాటులో లేదు. కెన్యా: విశ్లేషణ కెన్యా శాసనాలు, అనుబంధ చట్టం మరియు ప్రచురించబడిన హైకోర్టు మరియు అప్పీల్ నిర్ణయాలపై ఆధారపడి ఉంటుంది. ఇది ఆచార చట్టం, మేజిస్ట్రేట్ కోర్టు వైవిధ్యాలు లేదా ప్రచురించని తీర్పులను పరిగణనలోకి తీసుకోదు. యునైటెడ్ కింగ్‌డమ్: విశ్లేషణ ఇంగ్లీష్ మరియు వెల్ష్ చట్టాలను కవర్ చేస్తుంది. స్కాట్స్ చట్టం, నార్తర్న్ ఐరిష్ చట్టం, మరియు డెవలప్డ్ విషయాలు గణనీయంగా భిన్నంగా ఉండవచ్చు; అధికార పరిధి-నిర్దిష్ట సలహాను కోరండి.';

  @override
  String get legalDisclaimerJurisdictionHeading => '8. అధికార పరిమితులు';

  @override
  String get legalDisclaimerLawyerReviewBody =>
      'కొన్ని గొడుగు అవుట్‌పుట్‌లు \"అటార్నీ రివ్యూడ్\" బ్యాడ్జ్‌ను కలిగి ఉంటాయి, మా మార్కెట్‌ప్లేస్‌లో లైసెన్స్ పొందిన న్యాయవాది కంటెంట్‌ని సమీక్షించి, ఆమోదించారని సూచిస్తుంది. సమీక్షించిన అవుట్‌పుట్‌లు కూడా: (ఎ) సమీక్ష సమయంలో న్యాయవాది అభిప్రాయాన్ని ప్రతిబింబిస్తాయి; (బి) సంతకం చేసిన అభిప్రాయ లేఖతో పాటుగా తప్ప అధికారిక చట్టపరమైన అభిప్రాయాన్ని ఏర్పరచవద్దు; (సి) ప్రత్యేక రిటైనర్ ఒప్పందాన్ని అమలు చేయకపోతే న్యాయవాది-క్లయింట్ సంబంధాన్ని సృష్టించవద్దు; (డి) చట్టం మారినప్పుడు పాతది కావచ్చు. సమీక్షించే న్యాయవాది స్వతంత్ర కాంట్రాక్టర్; DVTech వెంచర్స్ ఏదైనా సమీక్షించబడిన అవుట్‌పుట్ యొక్క నాణ్యత లేదా ఖచ్చితత్వానికి హామీ ఇవ్వదు.';

