  @override
  String get legalDisclaimerNoPrivilegeBody =>
      'అంబ్రెల్లా యొక్క AIతో కమ్యూనికేషన్‌లు ఏ అధికార పరిధిలోనైనా అటార్నీ-క్లయింట్ ప్రత్యేకాధికారం లేదా చట్టపరమైన వృత్తిపరమైన ప్రత్యేకాధికారం ద్వారా రక్షించబడవు. మీరు ప్రివిలేజ్ కింద రక్షించాలని భావిస్తున్న ప్లాట్‌ఫారమ్‌కు సమాచారాన్ని సమర్పించవద్దు. మీరు అంబ్రెల్లా మార్కెట్‌ప్లేస్ ద్వారా లైసెన్స్ పొందిన లాయర్‌ని ఎంగేజ్ చేస్తే, ఎగ్జిక్యూటెడ్ రిటైనర్ ఒప్పందం ప్రకారం ఆ లాయర్‌తో మీ కమ్యూనికేషన్‌లకు ప్రివిలేజ్ జోడించబడవచ్చు, కానీ మీ మునుపటి AI పరస్పర చర్యలకు కాదు.';

