  @override
  String get legalDisclaimerPageDescription =>
      'అంబ్రెల్లా యొక్క AI- రూపొందించిన చట్టపరమైన సమాచారం, దాని పరిమితులు మరియు వినియోగదారు బాధ్యతల గురించి ముఖ్యమైన నోటీసులు. అంబ్రెల్లా ప్లాట్‌ఫారమ్ ద్వారా DVTech వెంచర్స్ అందించే అన్ని ఉత్పత్తులు మరియు ఫీచర్‌లకు ఈ నిరాకరణ వర్తిస్తుంది.';

  @override
  String get legalDisclaimerPageTitle => 'చట్టపరమైన నిరాకరణ';

  @override
  String get legalDisclaimerRegulatoryBody =>
      'DVTech వెంచర్స్ అనేది సాంకేతిక సంస్థ, నియంత్రిత న్యాయ సేవల ప్రదాత కాదు. న్యాయ సేవలను అందించడానికి సొలిసిటర్స్ రెగ్యులేషన్ అథారిటీ (UK), బార్ కౌన్సిల్ ఆఫ్ ఇండియా, లా సొసైటీ ఆఫ్ కెన్యా, ఏదైనా US స్టేట్ బార్ లేదా ఏదైనా ఇతర చట్టపరమైన నియంత్రణ సంస్థ ద్వారా మాకు అధికారం లేదు. గొడుగు ప్లాట్‌ఫారమ్ లీగల్ సర్వీసెస్ యాక్ట్ 2007 (UK) లేదా ఇతర అధికార పరిధిలోని సమానమైన చట్టాలలో నిర్వచించిన విధంగా నియంత్రిత చట్టపరమైన కార్యాచరణను అందించదు.';

  @override
  String get legalDisclaimerRegulatoryHeading => '9. రెగ్యులేటరీ స్థితి';

  @override
  String get legalDisclaimerRelianceBody =>
      'మీరు వీటిని అంగీకరిస్తున్నారు: (a) మీ చట్టపరమైన హక్కులు లేదా బాధ్యతలను ప్రభావితం చేసే నిర్ణయాలు తీసుకోవడానికి మీరు AI అవుట్‌పుట్‌లపై మాత్రమే ఆధారపడరు; (బి) మీరు చట్టపరమైన చర్యలను ప్రారంభించడం, సమర్థించడం లేదా పరిష్కరించే ముందు స్వతంత్ర అర్హత కలిగిన న్యాయ సలహాను కోరుకుంటారు; (సి) స్వతంత్ర ధృవీకరణ లేకుండా AI అవుట్‌పుట్‌లపై మీ ఆధారపడటం వల్ల ఉత్పన్నమయ్యే ఏదైనా హానికి DVTech వెంచర్స్ బాధ్యత వహించదు. ఈ పరిమితి వర్తించే చట్టం ద్వారా అనుమతించబడిన పూర్తి స్థాయికి వర్తిస్తుంది.';

  @override
  String get legalDisclaimerRelianceHeading => '6. ఆధారపడటంపై పరిమితి';

  @override
  String get legalDisclaimerScopeBody =>
      'ఈ నిరాకరణ అంబ్రెల్లా ప్లాట్‌ఫారమ్‌లోని ప్రతి ఫీచర్‌కి వర్తిస్తుంది, వీటికి మాత్రమే పరిమితం కాదు: లీగల్ ఇష్యూ చెకర్, AI కోపైలట్, డాక్యుమెంట్ రివ్యూ, లీగల్ రీసెర్చ్, మ్యాటర్ అనాలిసిస్, స్ట్రాటజీ మెమోలు, డ్రాఫ్ట్ డాక్యుమెంట్‌లు మరియు ఏదైనా ఇతర AI రూపొందించిన కంటెంట్. గొడుగు నిర్వహించే అన్ని అధికార పరిధిలో (భారతదేశం, యునైటెడ్ స్టేట్స్, కెన్యా మరియు యునైటెడ్ కింగ్‌డమ్) వినియోగదారులందరికీ - వినియోగదారులు, లాయర్ యూజర్‌లు మరియు న్యాయ సంస్థ అద్దెదారులందరికీ ఇది వర్తిస్తుంది.';

  @override
  String get legalDisclaimerScopeHeading => '1. ఈ నిరాకరణ యొక్క పరిధి';

  @override
  String get legalDisclaimerUniversalBody =>
      'గొడుగు చట్టపరమైన సమాచారం, డాక్యుమెంట్ వివరణ, ఇష్యూ స్పాటింగ్ మరియు రిస్క్ అనాలిసిస్ అందిస్తుంది. ఇది న్యాయ సంస్థ కాదు మరియు లైసెన్స్ పొందిన న్యాయవాదిని భర్తీ చేయదు. మీ పరిస్థితికి సంబంధించిన నిర్దిష్ట న్యాయ సలహా కోసం, మీ అధికార పరిధిలోని అర్హత కలిగిన న్యాయవాదిని సంప్రదించండి. AI- రూపొందించిన కంటెంట్ సమాచార ప్రయోజనాల కోసం మాత్రమే అందించబడింది మరియు ఇది న్యాయ సలహా, చట్టపరమైన ప్రాతినిధ్యం లేదా మీకు మరియు DVTech వెంచర్‌ల మధ్య న్యాయవాది-క్లయింట్ సంబంధాన్ని ఏర్పరచదు.';

  @override
  String get legalDisclaimerUniversalHeading => '2. యూనివర్సల్ నిరాకరణ';

  @override
  String get legalDisclaimerUserResponsibilitiesBody =>
      'ప్లాట్‌ఫారమ్‌ను ఉపయోగించడం ద్వారా మీరు దీని కోసం బాధ్యతను అంగీకరిస్తారు: (a) మీ నిర్దిష్ట పరిస్థితికి AI అవుట్‌పుట్‌ల యొక్క ఖచ్చితత్వం మరియు అనువర్తనాన్ని మూల్యాంకనం చేయడం; (బి) తగిన చోట స్వతంత్ర న్యాయ సలహా పొందడం; (సి) మీ AI అవుట్‌పుట్‌ల ఉపయోగం మీ వృత్తిపరమైన బాధ్యతలకు (లాయర్ యూజర్‌లు) అనుగుణంగా ఉందని నిర్ధారించుకోవడం; (డి) అధికారం లేకుండా మూడవ పక్షం రహస్య సమాచారాన్ని సమర్పించకపోవడం; (ఇ) మీ ఖాతా ఆధారాలను సురక్షితంగా ఉంచడం.';

