  @override
  String get legalPrivacyAutomatedBody =>
      'చట్టపరమైన విశ్లేషణను రూపొందించడానికి, సమస్యలను గుర్తించడానికి మరియు చర్యలను సూచించడానికి అంబ్రెల్లా AIని ఉపయోగిస్తుంది. ఈ AI అవుట్‌పుట్‌లు సమాచారానికి మాత్రమే సంబంధించినవి మరియు మీ చట్టపరమైన హక్కులకు సంబంధించి కట్టుబడి ఉండే నిర్ణయాలను కలిగి ఉండవు. మానవ సమీక్ష లేకుండా మీ గురించి చట్టపరమైన లేదా అదే విధంగా ముఖ్యమైన ప్రభావంతో పూర్తిగా ఆటోమేటెడ్ నిర్ణయం తీసుకోబడదు. మోసం గుర్తింపు కోసం మా AI రిస్క్-స్కోరింగ్ ప్లాట్‌ఫారమ్ యాక్సెస్‌ను ప్రభావితం చేయవచ్చు; మీరు అలాంటి నిర్ణయాన్ని మానవ సమీక్షను అభ్యర్థించవచ్చు.';

  @override
