  @override
  String get legalPrivacyLegalBasisBody =>
      'మేము మీ అధికార పరిధిని బట్టి క్రింది చట్టపరమైన స్థావరాల క్రింద వ్యక్తిగత డేటాను ప్రాసెస్ చేస్తాము: (a) ఒప్పందం — మీరు సైన్ అప్ చేసిన సేవలను అందించడానికి అవసరమైన ప్రాసెసింగ్; (బి) చట్టబద్ధమైన ఆసక్తులు - మోసం నివారణ, ప్లాట్‌ఫారమ్ భద్రత, ఉత్పత్తి మెరుగుదల; (సి) సమ్మతి - AI శిక్షణ, మార్కెటింగ్ ఇమెయిల్‌లు, ఖచ్చితంగా అవసరమైన కుక్కీలు; (d) చట్టపరమైన బాధ్యత - వర్తించే చట్టానికి అనుగుణంగా. భారతదేశం కోసం, ప్రాసెసింగ్ డిజిటల్ పర్సనల్ డేటా ప్రొటెక్షన్ యాక్ట్ 2023 (DPDP యాక్ట్) ద్వారా నిర్వహించబడుతుంది. UK/EU కోసం, ప్రాసెసింగ్ UK GDPR మరియు EU GDPRకి అనుగుణంగా ఉంటుంది. కెన్యా కోసం, ప్రాసెసింగ్ డేటా రక్షణ చట్టం 2019కి అనుగుణంగా ఉంటుంది. US వినియోగదారుల కోసం, మేము CCPA/CPRAతో సహా వర్తించే రాష్ట్ర గోప్యతా చట్టాలను పాటిస్తాము.';

  @override
  String get legalPrivacyLegalBasisHeading =>
      '2. ప్రాసెసింగ్ కోసం చట్టపరమైన ఆధారాలు';

  @override
  String get legalPrivacyPolicy => 'గోప్యతా విధానం';

  @override
  String get legalPrivacyRetentionBody =>
      'మీ ఖాతా సక్రియంగా ఉన్నంత వరకు మేము వ్యక్తిగత డేటాను అలాగే ఉంచుతాము. ఖాతా తొలగింపుపై, మేము వ్యక్తిగత డేటాను 30 రోజులలోపు తొలగిస్తాము లేదా అనామకంగా చేస్తాము, చట్టం ప్రకారం నిలుపుదల అవసరమయ్యే చోట మినహా (ఉదా., పన్ను సమ్మతి కోసం 7 సంవత్సరాల పాటు బిల్లింగ్ రికార్డ్‌లు, 12 నెలల పాటు ఆడిట్ లాగ్‌లు అలాగే ఉంచబడతాయి). సంస్థ అద్దెదారులు గవర్నెన్స్ సెట్టింగ్‌ల ద్వారా 7 సంవత్సరాల వరకు అనుకూల నిలుపుదల విధానాలను కాన్ఫిగర్ చేయవచ్చు. ఎంచుకున్న కంటెంట్ నుండి తీసుకోబడిన AI-శిక్షణ డేటాసెట్‌లు మా డేటా & AI సమ్మతి విధానంలోని నిలుపుదల షెడ్యూల్‌కు లోబడి ఉంటాయి.';

  @override
  String get legalPrivacyRetentionHeading => '6. నిలుపుదల';

  @override
  String get legalPrivacyRightsCCPABody =>
      'కాలిఫోర్నియా (CCPA/CPRA) హక్కులు: మేము సేకరిస్తున్న వ్యక్తిగత సమాచారాన్ని తెలుసుకునే హక్కు; తొలగించే హక్కు; విక్రయాన్ని నిలిపివేయడానికి హక్కు (మేము డేటాను విక్రయించము); హక్కులను వినియోగించుకోవడానికి వివక్ష చూపని హక్కు; సరికాని సమాచారాన్ని సరిచేసే హక్కు; సున్నితమైన వ్యక్తిగత సమాచార వినియోగాన్ని పరిమితం చేసే హక్కు.';

  @override
  String get legalPrivacyRightsDPDPBody =>
      'భారతదేశం DPDP చట్టం హక్కులు: మీ డిజిటల్ వ్యక్తిగత డేటాను యాక్సెస్ చేయడం, సరిదిద్దడం మరియు తొలగించడం; ఫిర్యాదుల పరిష్కార హక్కు; మీ తరపున హక్కులను వినియోగించుకోవడానికి ఒక వ్యక్తిని నామినేట్ చేసే హక్కు. support@odaflow.comలో మా సమ్మతి మేనేజర్‌ని సంప్రదించండి.';

  @override
  String get legalPrivacyRightsGDPRBody =>
      'GDPR / UK GDPR హక్కులు (EU మరియు UK వినియోగదారులు): యాక్సెస్ — మీ వ్యక్తిగత డేటా కాపీని పొందండి; సరిదిద్దడం - సరికాని డేటా; ఎరేజర్ - అభ్యర్థన తొలగింపు (చట్టపరమైన హోల్డ్‌కు లోబడి); పరిమితి - వివాదం పరిష్కరించబడినప్పుడు ప్రాసెసింగ్ పరిమితి; పోర్టబిలిటీ - మీ డేటాను మెషిన్-రీడబుల్ ఫార్మాట్‌లో స్వీకరించండి; అభ్యంతరం - చట్టబద్ధమైన ఆసక్తుల ఆధారంగా ప్రాసెస్ చేయడానికి వస్తువు; స్వయంచాలక నిర్ణయాలు - ముఖ్యమైన ప్రభావాలతో పూర్తిగా స్వయంచాలక నిర్ణయాలకు లోబడి ఉండకూడదు. ఈ హక్కులను వినియోగించుకోవడానికి, support@odaflow.comకు ఇమెయిల్ చేయండి లేదా యాప్‌లో గోప్యతా సెట్టింగ్‌లను ఉపయోగించండి.';

  @override
  String get legalPrivacyRightsHeading => '9. మీ హక్కులు';

  @override
  String get legalPrivacyRightsKenyaBody =>
      'కెన్యా డేటా రక్షణ చట్టం హక్కులు: తెలియజేయడానికి హక్కు; యాక్సెస్ హక్కు; సరిదిద్దే హక్కు; చెరిపివేయడం మరియు నిరోధించే హక్కు; వస్తువు హక్కు; డేటా పోర్టబిలిటీ హక్కు. support@odaflow.comలో మా స్థానిక ప్రతినిధిని సంప్రదించండి.';

  @override
  String get legalPrivacySecurityBody =>
      'మేము వీటితో సహా సాంకేతిక మరియు సంస్థాగత చర్యలను అమలు చేస్తాము: రవాణాలో TLS 1.2+ ఎన్‌క్రిప్షన్; విశ్రాంతి సమయంలో AES-256 ఎన్‌క్రిప్షన్; కనీస-ప్రత్యేక సూత్రాలతో పాత్ర-ఆధారిత యాక్సెస్ నియంత్రణ; అడ్మినిస్ట్రేటివ్ యాక్సెస్ కోసం బహుళ-కారకాల ప్రమాణీకరణ; స్వయంచాలక దుర్బలత్వ స్కానింగ్; కనీసం ఏటా చొచ్చుకుపోయే పరీక్ష; మరియు సంఘటన ప్రతిస్పందన ప్రణాళిక. మీ హక్కులను ప్రభావితం చేసే వ్యక్తిగత డేటా ఉల్లంఘన సందర్భంలో, వర్తించే చట్టం ప్రకారం అవసరమైన 72 గంటలలోపు మేము మీకు తెలియజేస్తాము.';

