  @override
  String get legalPrivacySharingLawyerReview =>
      'న్యాయవాది సమీక్ష: మీరు న్యాయవాది సమీక్షను అభ్యర్థిస్తే, మీ కేసు సారాంశం (మీరు దానిని ప్రామాణీకరించకపోతే పూర్తి కంటెంట్ కాదు) మా మార్కెట్‌ప్లేస్‌లో కేటాయించబడిన లైసెన్స్ పొందిన న్యాయవాదితో భాగస్వామ్యం చేయబడుతుంది. మీరు భాగస్వామ్యం చేయబడిన వాటిని నియంత్రించండి.';

